/**
 * Zero Club icon set — Solar (bold duotone).
 *
 * Every icon in the app comes from one family now. The app used to mix a
 * hand-drawn nav set with stock outline icons everywhere else, which is what
 * made the interface read as generic: two different weights, two different
 * grids, in the same screen.
 *
 * Duotone means each glyph is a solid shape with a second shape behind it at
 * 50% opacity. It carries far more presence at 16–20px than a hairline
 * outline, which is why premium wallet and finance apps have moved to it.
 *
 * The export names deliberately match the Lucide names they replaced, so call
 * sites did not have to change and a future change of family is one
 * regeneration of this file.
 *
 * Six primitives — check, close, plus, minus, circle, square — are drawn here
 * rather than taken from Solar. Duotone sets only offer them enclosed in a
 * circle or square, and a circled tick inside a button that is already a
 * circle looks like a mistake.
 *
 * Icons: Solar by 480 Design, CC BY 4.0 (https://www.figma.com/community/file/1166831539721848736).
 * Generated file — edit the generator, not this.
 */
import React from "react";

export type ZeroIconProps = React.SVGProps<SVGSVGElement> & {
  size?: number | string;
  /** Accepted and ignored: duotone glyphs are filled, not stroked. */
  strokeWidth?: number | string;
  absoluteStrokeWidth?: boolean;
};

/** Kept for call sites that typed a prop as `LucideIcon`. */
export type LucideIcon = React.FC<ZeroIconProps>;

function make(body: string, stroked = false): LucideIcon {
  return function ZeroIcon({ size, strokeWidth, absoluteStrokeWidth, className, ...rest }: ZeroIconProps) {
    return (
      <svg
        viewBox="0 0 24 24"
        width={size ?? 24}
        height={size ?? 24}
        fill={stroked ? "none" : "currentColor"}
        stroke={stroked ? "currentColor" : undefined}
        strokeWidth={stroked ? 2 : undefined}
        strokeLinecap={stroked ? "round" : undefined}
        strokeLinejoin={stroked ? "round" : undefined}
        aria-hidden="true"
        /* zc-icon is the handle the stylesheet uses to lift the duotone
           backing layer. Pulled out of the rest props rather than spread over,
           so a caller's own classes are kept rather than replaced. */
        className={className ? `zc-icon ${className}` : "zc-icon"}
        {...rest}
        dangerouslySetInnerHTML={{ __html: body }}
      />
    );
  };
}

